dtsPropsFor.AppLayout:
/** Page content, rendered inside the shell's Container. */
  children: React.ReactNode;
  /** The signed-in household member, shown in the header. */
  user: { id: string; username: string };

dtsPropsFor.ItemsCatalog:
/** Categories offered in the filter Select, with their item counts. */
  initialCategories: Array<{ id: string; name: string; itemCount: number; createdAt: Date; updatedAt: Date }>;
  /** Items to render; search, category and sort filtering run client-side over this list. */
  initialItems: Array<{ id: string; categoryId: string; categoryName: string; description: string | null; mainImage: string; additionalImages: string[]; createdById: string | null; createdByName: string; createdAt: Date; updatedAt: Date }>;

dtsPropsFor.UsersManager:
/** Household members to list. Never carries passwordHash. */
  initialUsers: Array<{ id: string; username: string; createdAt: Date }>;
  /** Id of the signed-in user — that row is badged and cannot be deleted. */
  currentUserId: string;

dtsPropsFor.EditItemForm:
/** The item being edited; its fields pre-fill the form. */
  item: { id: string; categoryId: string; categoryName: string; description: string | null; mainImage: string; additionalImages: string[]; createdById: string | null; createdByName: string; createdAt: Date; updatedAt: Date };
  /** Categories offered in the Select. Must contain item.categoryId. */
  categories: Array<{ id: string; name: string; itemCount: number; createdAt: Date; updatedAt: Date }>;

dtsPropsFor.ImageDropzone:
/** Called with the accepted files each time photos are dropped or picked. */
  onDrop: (files: File[]) => void;
  /** Bold line inside the dropzone. */
  title: string;
  /** Dimmed line under the title. */
  hint: string;
  disabled?: boolean;
  /** Which glyph to show at rest. `photo` for a first image, `plus` to add more. */
  idleIcon?: 'photo' | 'plus';
  /** Glyph edge length in px. */
  iconSize?: number;
  /** Minimum height of the drop target in px. */
  minHeight?: number;
  maxFiles?: number;
  /** Bottom margin, as a Mantine spacing token. */
  mb?: string;
  /** Tighter spacing and smaller copy, for the denser edit-form layout. */
  compact?: boolean;

dtsPropsFor.ImageLightboxModal:
opened: boolean;
  onClose: () => void;
  /** Stored image filenames, not URLs. */
  images: string[];
  /** Which image to open on. Defaults to 0. */
  initialIndex?: number;
  /** Shown in the modal header. */
  title?: string;
